package com.logiplatform.model;

import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;

@Entity @Table(name="ocean_bookings") public class OceanBooking { @Id @GeneratedValue UUID id; @Column(name="tenant_id",nullable=false,updatable=false) UUID tenantId; @Column(name="shipment_id",nullable=false) UUID shipmentId; @Column(name="voyage_id") UUID voyageId; @Column(name="booking_number",nullable=false) String bookingNumber; @Column(name="booking_type",nullable=false) String bookingType="FCL"; int requestedContainers=1,confirmedContainers; Instant cutoffDocument,cutoffCargo; String status="REQUESTED",carrierReference,notes; Instant createdAt=Instant.now(),updatedAt=Instant.now(); protected OceanBooking(){} public OceanBooking(UUID t,UUID s,UUID v,String no,String type,int req){tenantId=t;shipmentId=s;voyageId=v;bookingNumber=no;bookingType=type;requestedContainers=req;} public UUID getId(){return id;} public UUID getShipmentId(){return shipmentId;} public UUID getVoyageId(){return voyageId;} public String getBookingNumber(){return bookingNumber;} public String getBookingType(){return bookingType;} public int getRequestedContainers(){return requestedContainers;} public int getConfirmedContainers(){return confirmedContainers;} public String getStatus(){return status;} }
